-- ROPA v2 aligns the versioned application form with both supplied workbooks:
-- ROPA_Final_Template_Controller.xlsx and ROPA_Final_Template_Processor.xlsx.
-- Existing records retain their original form version.

INSERT INTO form_template_versions (form_template_id, version_number, definition, status, change_summary, created_by)
SELECT ft.id,
       (SELECT COALESCE(MAX(v.version_number), 0) + 1 FROM form_template_versions v WHERE v.form_template_id = ft.id),
       '{"sections":[{"title":"Record identity & organisation","description":"Core ROPA details shared by controller and processor records.","fields":[{"key":"record_id","label":"Record ID","type":"auto"},{"key":"client_id","label":"Organisation / Client","type":"client","required":true},{"key":"ropa_role","label":"ROPA role","type":"select","required":true,"options":["controller","processor"]},{"key":"department","label":"Department / business unit","type":"text"},{"key":"project","label":"Project name / processing context","type":"text"},{"key":"process_name","label":"Process / activity name","type":"text","required":true},{"key":"status","label":"Processing status","type":"select","options":["active","inactive","planned","under_review","paused","retired"]},{"key":"record_updated_date","label":"Date of entry / update","type":"auto"},{"key":"legal_frameworks","label":"Applicable legal frameworks","type":"multiselect","options":["GDPR","ISO 27701","CCPA/CPRA","DPDPA","Other"]}]},{"title":"Governance, purpose & legal basis","description":"Controller and processor responsibilities, purpose and applicable legal grounds.","fields":[{"key":"controller_role","label":"Processing role","type":"select","roles":["controller"],"options":["controller","joint_controller"]},{"key":"controller_name","label":"Controller name","type":"text","roles":["processor"]},{"key":"process_owner","label":"Process owner / contact","type":"text"},{"key":"dpo","label":"Data protection officer name / contact","type":"text"},{"key":"eu_representative","label":"EU representative (if applicable)","type":"text"},{"key":"purpose","label":"Purpose of processing","type":"textarea"},{"key":"processing_services","label":"Processing services","type":"multiselect","roles":["processor"],"options":["Cloud hosting / infrastructure","SaaS application services","Data storage & backup","Managed IT services","Customer support processing","CRM processing","Payroll processing","HR administration","Payment processing","Marketing services","Website & analytics","Security monitoring","Data analytics","AI / machine learning","Other"]},{"key":"processing_categories","label":"Categories of processing","type":"multiselect","roles":["processor"],"options":["Collection","Recording","Storage","Organisation","Retrieval","Consultation","Use","Sharing","Archiving","Deletion"]},{"key":"lawful_basis","label":"Lawful basis for processing","type":"multiselect","options":["Consent","Legitimate uses / legitimate interests","Contract","Legal obligation","Public interest","Vital interests","Other"]},{"key":"privacy_notice_reference","label":"Privacy notice reference","type":"text","roles":["controller"]}]},{"title":"Data mapping, classification & lifecycle","description":"Data subjects, categories, sources, systems, locations and retention.","fields":[{"key":"data_subject_categories","label":"Data-subject categories","type":"multiselect","options":["Employees","Customers / clients","Job applicants / candidates","Website / app users","Contractors / vendors / suppliers","Shareholders / investors","Children","Persons with disabilities","Business contacts","Other"]},{"key":"personal_data_categories","label":"Personal-data categories","type":"multiselect","options":["PII","Sensitive personal information","Contact details","Financial data","Account data","Online identifiers","Employment data","Other"]},{"key":"special_data","label":"Special-category / sensitive data","type":"multiselect","options":["Health data","Genetic data","Biometric data","Payment-card data","Financial credentials","Government IDs","Precise geolocation","Racial or ethnic origin","Religious beliefs","Political opinions","Trade-union membership","Sex-life or sexual-orientation data","Criminal-history data","Private communications","Other"]},{"key":"large_scale_processing","label":"Large-scale processing","type":"select","roles":["controller"],"options":["yes","no"]},{"key":"data_source","label":"Source of personal data","type":"multiselect","options":["Directly from data subject","Controller","Third party","Cookies / website analytics","Integration","Publicly available source","Server logs","Other"]},{"key":"data_format","label":"Data format","type":"select","options":["paper","digital","both"]},{"key":"hosting_system","label":"Primary hosting system / asset","type":"text"},{"key":"processing_environment","label":"Processing environment","type":"select","options":["on_premise","cloud","hybrid","other"]},{"key":"storage_countries","label":"Data-storage locations / countries","type":"text"},{"key":"dpdpa_whitelist_status","label":"Country whitelisted under DPDPA","type":"select","options":["yes","no","not_assessed"]},{"key":"data_volume","label":"Data volume","type":"select","options":["under_100000","100000_to_6_million","over_6_million","systematic_public_monitoring","other"]},{"key":"processing_frequency","label":"Processing frequency","type":"select","options":["one_time","ad_hoc","monthly","quarterly","bi_annually","annually","continuous","on_significant_change","on_risk_change"]},{"key":"retention_period","label":"Retention period / storage limitation","type":"text"},{"key":"retention_controller_instruction","label":"Retention / data-return instruction from controller","type":"textarea","roles":["processor"]},{"key":"disposal_date","label":"Disposal / deletion / return date","type":"date"},{"key":"disposal_method","label":"Disposal / deletion method","type":"textarea"},{"key":"retention_disposal_policy_reference","label":"Retention & disposal policy reference","type":"text","roles":["controller"]}]},{"title":"Sharing, recipients, processors & transfers","description":"Recipients, third parties, sub-processors and international transfers.","fields":[{"key":"sale_or_sharing","label":"Sale or sharing of personal information","type":"select","options":["yes","no","not_applicable"]},{"key":"data_sharing_scope","label":"Data sharing scope","type":"select","options":["internal","external","both","none"]},{"key":"internal_recipients","label":"Internal recipients","type":"textarea"},{"key":"external_recipients","label":"External recipients","type":"textarea"},{"key":"processors","label":"Processors / controllers / sub-processors","type":"textarea","roles":["controller"]},{"key":"subprocessors","label":"Sub-processors / third-party processors","type":"textarea","roles":["processor"]},{"key":"international_transfer","label":"Cross-border / international transfer","type":"select","options":["yes","no"]},{"key":"transfer_safeguards","label":"Transfer mechanism / safeguards","type":"multiselect","options":["SCCs","Binding corporate rules","Data privacy framework","Adequacy decision","DPDPA section 16","Other"]},{"key":"dpa_reference","label":"Data-processing agreement reference","type":"text"},{"key":"joint_controller_agreement","label":"Joint-controller arrangement reference","type":"text","roles":["controller"]},{"key":"third_party_risk_assessment","label":"Third-party risk-assessment reference","type":"text","roles":["controller"]}]},{"title":"Security, DPIA, rights & review","description":"Security controls, risk assessment, data-subject rights, incident management and review.","fields":[{"key":"security_measures","label":"Technical & organisational security measures","type":"textarea"},{"key":"security_per_controller_instruction","label":"Security measures implemented to controller instructions","type":"select","roles":["processor"],"options":["yes","no","partially","not_assessed"]},{"key":"privacy_by_design","label":"Privacy by design & default applicable","type":"select","roles":["controller"],"options":["yes","no","not_assessed"]},{"key":"dpia_applicability","label":"DPIA applicable","type":"select","options":["yes","no","completed","under_review"]},{"key":"dpia_triggers","label":"DPIA trigger(s)","type":"multiselect","roles":["controller"],"options":["Large-scale data","Sensitive data","Systematic profiling","Public monitoring","New technology","Data matching","Invisible processing","Vulnerable subjects","Biometric identification","Genetic data","Other"]},{"key":"linked_dpia","label":"Linked DPIA reference ID","type":"text"},{"key":"dpia_assistance","label":"Processor assists controller with DPIA","type":"select","roles":["processor"],"options":["yes","no","not_applicable"]},{"key":"lia_reference","label":"Legitimate-interest assessment reference","type":"text","roles":["controller"]},{"key":"privacy_risk_rating","label":"Privacy risk rating","type":"select","options":["low","medium","high","critical"]},{"key":"consent_mechanism","label":"Consent mechanism implemented","type":"select","roles":["controller"],"options":["yes","no","not_applicable"]},{"key":"adm_profiling","label":"Automated decision-making / profiling","type":"select","options":["yes","no"]},{"key":"adm_profiling_details","label":"ADM / profiling details","type":"textarea"},{"key":"dsar_mechanism","label":"Data-subject rights management mechanism","type":"multiselect","roles":["controller"],"options":["All rights","Right to be informed","Access","Rectification / correction","Erasure / deletion","Data portability","Object / opt out","Restrict processing","Limit sensitive-data use","Non-automated decision making","Withdraw consent","Grievance redressal","Nominate","Accounting of disclosures","Request restrictions"]},{"key":"dsar_support","label":"DSAR support process established","type":"select","roles":["processor"],"options":["yes","no","not_applicable"]},{"key":"data_subject_requests","label":"Data-subject requests / complaints record","type":"textarea"},{"key":"breach_management","label":"Personal-data breach / incident management","type":"textarea"},{"key":"last_audit_date","label":"Last audit / review date","type":"date"},{"key":"last_audit_performed_by","label":"Last audit performed by","type":"text","roles":["processor"]},{"key":"next_review_date","label":"Next scheduled review date","type":"date"},{"key":"approver","label":"Approver (management / DPO)","type":"text"},{"key":"remarks","label":"Remarks / notes","type":"textarea"}]}]}',
       'published',
       'Align ROPA with controller and processor workbook templates',
       NULL
FROM form_templates ft
WHERE ft.slug = 'ropa'
  AND NOT EXISTS (
      SELECT 1 FROM form_template_versions v
      WHERE v.form_template_id = ft.id
        AND v.change_summary = 'Align ROPA with controller and processor workbook templates'
  );

UPDATE form_template_versions v
JOIN form_templates ft ON ft.id = v.form_template_id
SET v.status = 'archived'
WHERE ft.slug = 'ropa'
  AND v.status = 'published'
  AND v.change_summary <> 'Align ROPA with controller and processor workbook templates';

UPDATE form_templates ft
JOIN form_template_versions v ON v.form_template_id = ft.id
SET ft.active_version_id = v.id
WHERE ft.slug = 'ropa'
  AND v.change_summary = 'Align ROPA with controller and processor workbook templates';
